-- PostgreSQL equivalent of deployed Sites v39. Additive migration only.
CREATE TABLE passlist.staff_access(email text PRIMARY KEY,owner_id text NOT NULL,role text NOT NULL CHECK(role IN('editor','viewer')),active bigint NOT NULL DEFAULT 1 CHECK(active IN(0,1)),reason text NOT NULL,granted_by text NOT NULL,updated_at text NOT NULL);
CREATE INDEX staff_access_owner ON passlist.staff_access(owner_id,active);
CREATE TABLE passlist.audit_events(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 kind text NOT NULL,table_name text NOT NULL,target_id text NOT NULL,operation text NOT NULL,owner_id text NOT NULL,request_id text NOT NULL,actor_id text NOT NULL,actor_email text NOT NULL,actor_role text NOT NULL,path text NOT NULL,method text NOT NULL,action text NOT NULL,ip text NOT NULL,user_agent text NOT NULL,status bigint,before_json text,after_json text,created_at text NOT NULL
);
CREATE INDEX audit_events_owner_id ON passlist.audit_events(owner_id,id);
CREATE INDEX audit_events_actor_time ON passlist.audit_events(actor_email,created_at);
CREATE INDEX audit_events_target ON passlist.audit_events(table_name,target_id,id);
ALTER TABLE passlist.staff_access ENABLE ROW LEVEL SECURITY;
ALTER TABLE passlist.audit_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON passlist.staff_access,passlist.audit_events FROM PUBLIC,anon,authenticated;
CREATE FUNCTION passlist.capture_evidence() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $fn$
DECLARE b jsonb; a jsonb; row_data jsonb; c jsonb; target text; owner text;
BEGIN
 -- An isolated, temporary importer copies pre-existing evidence verbatim.
 IF session_user='passlist_migrator' THEN IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END IF;
 c:=COALESCE(NULLIF(current_setting('passlist.audit_context',true),''),'{}')::jsonb;
 IF TG_TABLE_NAME='source_files' THEN
  IF TG_OP<>'INSERT' THEN b:=jsonb_build_object('key',OLD.key,'content_type',OLD.content_type,'content_bytes',octet_length(OLD.content),'sha256',encode(sha256(OLD.content),'hex')); END IF;
  IF TG_OP<>'DELETE' THEN a:=jsonb_build_object('key',NEW.key,'content_type',NEW.content_type,'content_bytes',octet_length(NEW.content),'sha256',encode(sha256(NEW.content),'hex')); END IF;
 ELSE
  IF TG_OP<>'INSERT' THEN b:=to_jsonb(OLD); END IF;
  IF TG_OP<>'DELETE' THEN a:=to_jsonb(NEW); END IF;
 END IF;
 IF b IS NOT DISTINCT FROM a THEN IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END IF;
 row_data:=COALESCE(a,b);
 target:=CASE WHEN TG_TABLE_NAME='audit' THEN row_data->>'target_id' ELSE COALESCE(row_data->>'id',row_data->>'email',row_data->>'key',row_data->>'batch_id',concat_ws(':',row_data->>'owner_id',row_data->>'dataset_version',row_data->>'source_row',row_data->>'version')) END;
 owner:=COALESCE(row_data->>'owner_id',c->>'owner_id','');
 INSERT INTO passlist.audit_events(kind,table_name,target_id,operation,owner_id,request_id,actor_id,actor_email,actor_role,path,method,action,ip,user_agent,status,before_json,after_json,created_at)
 VALUES('change',TG_TABLE_NAME,COALESCE(target,''),TG_OP,owner,COALESCE(c->>'request_id',''),COALESCE(c->>'actor_id',''),COALESCE(c->>'actor_email',''),COALESCE(c->>'actor_role','database'),COALESCE(c->>'path',''),COALESCE(c->>'method',''),COALESCE(c->>'action',''),COALESCE(c->>'ip',''),COALESCE(c->>'user_agent',''),NULL,b::text,a::text,to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
 IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $fn$;
REVOKE ALL ON FUNCTION passlist.capture_evidence() FROM PUBLIC,anon,authenticated;
CREATE FUNCTION passlist.prevent_evidence_mutation() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $fn$ BEGIN RAISE EXCEPTION 'Audit evidence is append-only'; END $fn$;
REVOKE ALL ON FUNCTION passlist.prevent_evidence_mutation() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER evidence_no_update_delete BEFORE UPDATE OR DELETE ON passlist.audit_events FOR EACH ROW EXECUTE FUNCTION passlist.prevent_evidence_mutation();
CREATE TRIGGER evidence_no_truncate BEFORE TRUNCATE ON passlist.audit_events FOR EACH STATEMENT EXECUTE FUNCTION passlist.prevent_evidence_mutation();
DO $triggers$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['audit','batches','records','exam_statistics','temple_registry','temple_registry_meta','organization_registry','organization_registry_meta','province_region_meta','retained_exam_statistics','statistics_sources','staff_access','source_files'] LOOP
  EXECUTE format('CREATE TRIGGER evidence_changes AFTER INSERT OR UPDATE OR DELETE ON passlist.%I FOR EACH ROW EXECUTE FUNCTION passlist.capture_evidence()',t);
 END LOOP;
END $triggers$;
